                        gv[o] = 1'b1;
                        gi[o] = idx;
                    end
                end
            end
        end
        for (int o = 0; o < 5; o++) begin
            if (gv[o] && !rst) in_ready[gi[o]] = 1'b1;
        end
    end

    // state
    always_ff @(posedge clk) begin
        for (int o = 0; o < 5; o++) begin
            if (rst) begin
                v[o]   <= 1'b0;
                cur[o] <= 3'd0;
            end else begin
                if (v[o] && out_ready[o])
                    cur[o] <= (src[o] == 3'd4) ? 3'd0 : src[o] + 3'd1;
                if (gv[o]) begin
                    v[o]    <= 1'b1;
                    data[o] <= in_flit[gi[o]*F +: F];
                    src[o]  <= gi[o];
                end else if (out_ready[o]) begin
                    v[o] <= 1'b0;
                end
            end
        end
    end

    always_comb begin
        out_valid = v;
        for (int o = 0; o < 5; o++)
            out_flit[o*F +: F] = v[o] ? data[o] : '0;
    end
endmodule

module noc_router5 #(
