        for (int i = 0; i < 5; i++) begin
            dx = in_flit[i*F + F-1 -: 2];
            dy = in_flit[i*F + F-3 -: 2];
            if (dx > X)      d = 3'd2;
            else if (dx < X) d = 3'd3;
            else if (dy > Y) d = 3'd0;
            else if (dy < Y) d = 3'd1;
            else             d = 3'd4;
            if (in_valid[i]) req[d][i] = 1'b1;
        end

        gnt = '0;
        gv  = '0;
        nf  = '0;
        for (int o = 0; o < 5; o++) begin
            sc    = (src[o] == 3'd4) ? 3'd0 : src[o] + 3'd1;
            s     = (v[o] && out_ready[o]) ? sc : cur[o];
            avail = !v[o] || out_ready[o];
            r     = avail ? arb(s, req[o]) : 4'd0;
            gv[o] = r[3];
            for (int i = 0; i < 5; i++) begin
                if (r[3] && r[2:0] == 3'(i)) begin
                    gnt[o][i] = 1'b1;
                    nf[o]     = in_flit[i*F +: F];
                end
            end
        end

        for (int i = 0; i < 5; i++) begin
            in_ready[i] = !rst && (gnt[0][i] | gnt[1][i] | gnt[2][i] |
                                   gnt[3][i] | gnt[4][i]);
        end
    end

    always_ff @(posedge clk) begin
        for (int o = 0; o < 5; o++) begin
            if (rst) begin
                v[o]   <= 1'b0;
                cur[o] <= 3'd0;
            end else begin
                if (v[o] && out_ready[o])
                    cur[o] <= (src[o] == 3'd4) ? 3'd0 : src[o] + 3'd1;
                if (gv[o]) begin
                    v[o]    <= 1'b1;
                    data[o] <= nf[o];
                    for (int i = 0; i < 5; i++)
                        if (gnt[o][i]) src[o] <= 3'(i);
                end else if (out_ready[o]) begin
                    v[o] <= 1'b0;
                end
            end
        end
    end

    always_comb begin
        out_valid = v;
        for (int o = 0; o < 5; o++)
            out_flit[o*F +: F] = v[o] ? data[o] : '0;
    end
endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);
    localparam int F = 4 + PAYLOAD_W;

    logic [4:0]   v;
    logic [F-1:0] fl  [5];
    logic [2:0]   src [5];
    logic [2:0]   cur [5];

    logic [2:0] dst [5];
    logic [4:0] gnt [5];
    logic [2:0] gsrc [5];
    logic [4:0] drain;
    logic [4:0] acc;

    logic [1:0] dx, dy;
    logic [2:0] start;
    logic       found;
    int         idx;

    always_comb begin
        in_ready = '0;
        for (int i = 0; i < 5; i++) begin
            dx = in_flit[i*F+PAYLOAD_W+2 +: 2];
            dy = in_flit[i*F+PAYLOAD_W +: 2];
            if (dx > X)      dst[i] = 3'd2;
            else if (dx < X) dst[i] = 3'd3;
            else if (dy > Y) dst[i] = 3'd0;
            else if (dy < Y) dst[i] = 3'd1;
            else             dst[i] = 3'd4;
        end
        for (int o = 0; o < 5; o++) begin
            drain[o] = v[o] & out_ready[o];
            if (drain[o]) start = (src[o] == 3'd4) ? 3'd0 : src[o] + 3'd1;
            else          start = cur[o];
            found   = 1'b0;
            gnt[o]  = '0;
            gsrc[o] = 3'd0;
            for (int k = 0; k < 5; k++) begin
                idx = int'(start) + k;
                if (idx >= 5) idx = idx - 5;
                if (!found && !rst && (!v[o] || out_ready[o]) &&
                    in_valid[idx] && (int'(dst[idx]) == o)) begin
                    found     = 1'b1;
                    gnt[o][idx] = 1'b1;
                    gsrc[o]   = 3'(idx);
                end
            end
            acc[o] = found;
            in_ready = in_ready | gnt[o];
        end
    end

    always_comb begin
        out_valid = v;
        for (int o = 0; o < 5; o++)
            out_flit[o*F +: F] = v[o] ? fl[o] : '0;
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            v <= '0;
            for (int o = 0; o < 5; o++) begin
                fl[o]  <= '0;
                src[o] <= 3'd0;
                cur[o] <= 3'd0;
            end
        end else begin
            for (int o = 0; o < 5; o++) begin
                if (drain[o])
                    cur[o] <= (src[o] == 3'd4) ? 3'd0 : src[o] + 3'd1;
                if (acc[o]) begin
                    v[o]   <= 1'b1;
                    fl[o]  <= in_flit[int'(gsrc[o])*F +: F];
                    src[o] <= gsrc[o];
                end else if (drain[o]) begin
                    v[o]   <= 1'b0;
                    fl[o]  <= '0;
                end
            end
        end
    end
endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);
    localparam int F = 4 + PAYLOAD_W;

    // registered state (packed for robust simulation sensitivity)
    logic [4:0]     v   = '0;
    logic [5*F-1:0] fl  = '0;
    logic [14:0]    src = '0;
    logic [14:0]    cur = '0;

    // combinational
    logic [14:0] dst;
    logic [14:0] gsrc;
    logic [4:0]  drain;
    logic [4:0]  acc;

    logic [1:0] dx, dy;
    logic [2:0] start;
    logic [2:0] s3;
    logic       found;
    int         idx;
    logic [4:0] rdy;

    always_comb begin
        rdy  = '0;
        dst  = '0;
        gsrc = '0;
        acc  = '0;
        drain = v & out_ready;
        dx = 2'd0;
        dy = 2'd0;
        start = 3'd0;
        s3 = 3'd0;
        found = 1'b0;
        idx = 0;

        for (int i = 0; i < 5; i++) begin
            dx = in_flit[i*F+PAYLOAD_W+2 +: 2];
            dy = in_flit[i*F+PAYLOAD_W +: 2];
            if (dx > X)      dst[i*3 +: 3] = 3'd2;
            else if (dx < X) dst[i*3 +: 3] = 3'd3;
            else if (dy > Y) dst[i*3 +: 3] = 3'd0;
            else if (dy < Y) dst[i*3 +: 3] = 3'd1;
            else             dst[i*3 +: 3] = 3'd4;
        end

        for (int o = 0; o < 5; o++) begin
            s3 = src[o*3 +: 3];
            if (drain[o]) start = (s3 == 3'd4) ? 3'd0 : s3 + 3'd1;
            else          start = cur[o*3 +: 3];
            found = 1'b0;
            for (int k = 0; k < 5; k++) begin
                idx = int'(start) + k;
                if (idx >= 5) idx = idx - 5;
                if (!found && !rst && (!v[o] || out_ready[o]) &&
                    in_valid[idx] && (int'(dst[idx*3 +: 3]) == o)) begin
                    found = 1'b1;
                    rdy[idx] = 1'b1;
                    gsrc[o*3 +: 3] = 3'(idx);
                end
            end
            acc[o] = found;
        end

        in_ready  = rdy;
        out_valid = v;
        for (int o = 0; o < 5; o++)
            out_flit[o*F +: F] = v[o] ? fl[o*F +: F] : {F{1'b0}};
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            v   <= '0;
            fl  <= '0;
            src <= '0;
            cur <= '0;
        end else begin
            for (int o = 0; o < 5; o++) begin
                if (drain[o])
                    cur[o*3 +: 3] <= (src[o*3 +: 3] == 3'd4) ? 3'd0 : src[o*3 +: 3] + 3'd1;
                if (acc[o]) begin
                    v[o]            <= 1'b1;
                    fl[o*F +: F]    <= in_flit[int'(gsrc[o*3 +: 3])*F +: F];
                    src[o*3 +: 3]   <= gsrc[o*3 +: 3];
                end else if (drain[o]) begin
                    v[o]            <= 1'b0;
                    fl[o*F +: F]    <= '0;
                end
            end
        end
    end
endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);
    localparam int F = 4 + PAYLOAD_W;

    function automatic logic [2:0] route(input logic [1:0] dx, input logic [1:0] dy);
        if (dx > X)      route = 3'd2;
        else if (dx < X) route = 3'd3;
        else if (dy > Y) route = 3'd0;
        else if (dy < Y) route = 3'd1;
        else             route = 3'd4;
    endfunction

    // returns {found, index}; first requester at or after st (cyclic) wins
    function automatic logic [3:0] pick(input logic [4:0] r, input logic [2:0] st);
        logic [3:0] res;
        int idx;
        res = 4'd0;
        for (int k = 4; k >= 0; k--) begin
            idx = int'(st) + k;
            if (idx >= 5) idx = idx - 5;
            if (r[idx]) res = {1'b1, 3'(idx)};
        end
        return res;
    endfunction

    logic [14:0] dstw;
    logic [24:0] gnt;

    genvar i, o;
    generate
        for (i = 0; i < 5; i++) begin : g_route
            assign dstw[i*3 +: 3] = route(in_flit[i*F+PAYLOAD_W+2 +: 2],
                                          in_flit[i*F+PAYLOAD_W +: 2]);
            assign in_ready[i] = gnt[i] | gnt[5+i] | gnt[10+i] | gnt[15+i] | gnt[20+i];
        end

        for (o = 0; o < 5; o++) begin : g_out
            logic         v   = 1'b0;
            logic [F-1:0] fl  = '0;
            logic [2:0]   src = 3'd0;
            logic [2:0]   cur = 3'd0;

            logic [4:0]   req;
            logic [2:0]   nxt;
            logic [2:0]   start;
            logic         drain;
            logic         avail;
            logic [3:0]   pk;
            logic         acc;
            logic [4:0]   gl;
            logic [F-1:0] din;

            for (i = 0; i < 5; i++) begin : g_req
                assign req[i] = in_valid[i] && (dstw[i*3 +: 3] == 3'(o));
            end

            assign nxt   = (src == 3'd4) ? 3'd0 : src + 3'd1;
            assign drain = v & out_ready[o];
            assign avail = ~v | out_ready[o];
            assign start = drain ? nxt : cur;
            assign pk    = pick(req & {5{avail & ~rst}}, start);
            assign acc   = pk[3];

            always_comb begin
                din = '0;
                for (int j = 0; j < 5; j++) begin
                    gl[j] = acc && (pk[2:0] == 3'(j));
                    din   = din | (in_flit[j*F +: F] & {F{gl[j]}});
                end
            end

            assign gnt[o*5 +: 5]    = gl;
            assign out_valid[o]     = v;
            assign out_flit[o*F +: F] = v ? fl : {F{1'b0}};

            always_ff @(posedge clk) begin
                if (rst) begin
                    v   <= 1'b0;
                    fl  <= '0;
                    src <= 3'd0;
                    cur <= 3'd0;
                end else begin
                    if (drain) cur <= nxt;
                    if (acc) begin
                        v   <= 1'b1;
                        fl  <= din;
                        src <= pk[2:0];
                    end else if (drain) begin
                        v   <= 1'b0;
                        fl  <= '0;
                    end
                end
            end
        end
    endgenerate
endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);
    localparam int F = 4 + PAYLOAD_W;

    logic [F-1:0] slot_flit [5];
    logic [2:0]   slot_src  [5];
    logic [2:0]   cursor    [5];
    logic [4:0]   slot_v;

    logic [2:0]   req  [5];
    logic [2:0]   gsel [5];
    logic [4:0]   gany;

    function automatic logic [2:0] succ(input logic [2:0] s);
        return (s == 3'd4) ? 3'd0 : s + 3'd1;
    endfunction

    always_comb begin
        logic [1:0] dx, dy;
        logic [2:0] start, idx;
        logic       found;
        for (int i = 0; i < 5; i++) begin
            dx = in_flit[i*F + PAYLOAD_W + 2 +: 2];
            dy = in_flit[i*F + PAYLOAD_W +: 2];
            if (dx > X)      req[i] = 3'd2;
            else if (dx < X) req[i] = 3'd3;
            else if (dy > Y) req[i] = 3'd0;
            else if (dy < Y) req[i] = 3'd1;
            else             req[i] = 3'd4;
        end
        in_ready = 5'b0;
        for (int o = 0; o < 5; o++) begin
            start = (slot_v[o] && out_ready[o]) ? succ(slot_src[o]) : cursor[o];
            found = 1'b0;
            gsel[o] = 3'd0;
            for (int k = 0; k < 5; k++) begin
                idx = start + 3'(k);
                if (idx >= 3'd5) idx = idx - 3'd5;
                if (!found && (!slot_v[o] || out_ready[o]) && in_valid[idx] &&
                    req[idx] == 3'(o) && !rst) begin
                    found = 1'b1;
                    gsel[o] = idx;
                end
            end
            gany[o] = found;
            if (found) in_ready[gsel[o]] = 1'b1;
        end
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            slot_v <= 5'b0;
            for (int o = 0; o < 5; o++) begin
                cursor[o]    <= 3'd0;
                slot_flit[o] <= '0;
                slot_src[o]  <= 3'd0;
            end
        end else begin
            for (int o = 0; o < 5; o++) begin
                if (slot_v[o] && out_ready[o])
                    cursor[o] <= succ(slot_src[o]);
                if (gany[o]) begin
                    slot_v[o]    <= 1'b1;
                    slot_flit[o] <= in_flit[gsel[o]*F +: F];
                    slot_src[o]  <= gsel[o];
                end else if (slot_v[o] && out_ready[o]) begin
                    slot_v[o] <= 1'b0;
                end
            end
        end
    end

    always_comb begin
        out_valid = slot_v;
        for (int o = 0; o < 5; o++)
            out_flit[o*F +: F] = slot_v[o] ? slot_flit[o] : '0;
    end
endmodule

module noc_router5 #(
