            out_flit[o*F +: F] = slot_v[o] ? slot_flit[o*F +: F] : '0;
    end
endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);
    localparam int F = 4 + PAYLOAD_W;

    logic [4:0]   v;
    logic [F-1:0] data [5];
    logic [2:0]   cur  [5];
    logic [2:0]   src  [5];

    logic [4:0]   req [5];     // req[o][i]: input i requests output o
    logic [4:0]   gv;          // grant valid per output
    logic [2:0]   gs [5];      // granted source per output
    logic [4:0]   drain;

    always_comb begin
        logic [1:0] dx, dy;
        logic [2:0] start, idx;
        logic [3:0] sum;
        for (int o = 0; o < 5; o++) req[o] = 5'b0;
        for (int i = 0; i < 5; i++) begin
            dx = in_flit[i*F + PAYLOAD_W + 2 +: 2];
            dy = in_flit[i*F + PAYLOAD_W +: 2];
            if (in_valid[i]) begin
                if (dx > X)      req[2][i] = 1'b1;
                else if (dx < X) req[3][i] = 1'b1;
                else if (dy > Y) req[0][i] = 1'b1;
                else if (dy < Y) req[1][i] = 1'b1;
                else             req[4][i] = 1'b1;
            end
        end
        in_ready = 5'b0;
        for (int o = 0; o < 5; o++) begin
            drain[o] = v[o] & out_ready[o];
            if (v[o]) start = (src[o] == 3'd4) ? 3'd0 : src[o] + 3'd1;
            else      start = cur[o];
            gv[o] = 1'b0;
            gs[o] = 3'd0;
            if (!rst && (!v[o] || out_ready[o])) begin
                for (int k = 0; k < 5; k++) begin
                    sum = {1'b0, start} + 4'(k);
                    if (sum >= 4'd5) sum = sum - 4'd5;
                    idx = sum[2:0];
                    if (!gv[o] && req[o][idx]) begin
                        gv[o] = 1'b1;
                        gs[o] = idx;
                    end
                end
            end
            if (gv[o]) in_ready[gs[o]] = 1'b1;
        end
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            v <= 5'b0;
            for (int o = 0; o < 5; o++) begin
                cur[o]  <= 3'd0;
                src[o]  <= 3'd0;
                data[o] <= '0;
            end
        end else begin
            for (int o = 0; o < 5; o++) begin
                if (drain[o])
                    cur[o] <= (src[o] == 3'd4) ? 3'd0 : src[o] + 3'd1;
                if (gv[o]) begin
                    v[o]    <= 1'b1;
                    data[o] <= in_flit[gs[o]*F +: F];
                    src[o]  <= gs[o];
                end else if (drain[o]) begin
                    v[o] <= 1'b0;
                end
            end
        end
    end

    assign out_valid = v;
    always_comb begin
        for (int o = 0; o < 5; o++)
            out_flit[o*F +: F] = v[o] ? data[o] : '0;
    end
endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);
    localparam int F = 4 + PAYLOAD_W;

    logic [4:0]       v;
    logic [5*F-1:0]   data;
    logic [14:0]      cur;   // 3 bits per output
    logic [14:0]      src;   // 3 bits per output

    logic [24:0]      req;   // req[o*5+i]
    logic [4:0]       gv;
    logic [14:0]      gs;
    logic [4:0]       drain;
    logic [14:0]      nxt;   // successor of src per output

    always_comb begin
        int s, idx, start;
        logic [1:0] dx, dy;
        req = 25'b0;
        for (int i = 0; i < 5; i++) begin
            dx = in_flit[i*F + PAYLOAD_W + 2 +: 2];
            dy = in_flit[i*F + PAYLOAD_W +: 2];
            if (in_valid[i]) begin
                if (dx > X)      req[2*5+i] = 1'b1;
                else if (dx < X) req[3*5+i] = 1'b1;
                else if (dy > Y) req[0*5+i] = 1'b1;
                else if (dy < Y) req[1*5+i] = 1'b1;
                else             req[4*5+i] = 1'b1;
            end
        end
        in_ready = 5'b0;
        gv = 5'b0;
        gs = 15'b0;
        nxt = 15'b0;
        drain = v & out_ready;
        for (int o = 0; o < 5; o++) begin
            s = int'(src[o*3 +: 3]);
            s = (s + 1) % 5;
            nxt[o*3 +: 3] = 3'(s);
            if (v[o]) start = s;
            else      start = int'(cur[o*3 +: 3]);
            if (!rst && (!v[o] || out_ready[o])) begin
                for (int k = 0; k < 5; k++) begin
                    idx = (start + k) % 5;
                    if (!gv[o] && req[o*5+idx]) begin
                        gv[o] = 1'b1;
                        gs[o*3 +: 3] = 3'(idx);
                    end
                end
            end
            if (gv[o]) in_ready[int'(gs[o*3 +: 3])] = 1'b1;
        end
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            v    <= 5'b0;
            cur  <= 15'b0;
            src  <= 15'b0;
            data <= '0;
        end else begin
            for (int o = 0; o < 5; o++) begin
                if (drain[o])
                    cur[o*3 +: 3] <= nxt[o*3 +: 3];
                if (gv[o]) begin
                    v[o] <= 1'b1;
                    data[o*F +: F] <= in_flit[int'(gs[o*3 +: 3])*F +: F];
                    src[o*3 +: 3] <= gs[o*3 +: 3];
                end else if (drain[o]) begin
                    v[o] <= 1'b0;
                end
            end
        end
    end

    assign out_valid = v;
    always_comb begin
        for (int o = 0; o < 5; o++)
            out_flit[o*F +: F] = v[o] ? data[o*F +: F] : {F{1'b0}};
    end
endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);
    localparam int F = 4 + PAYLOAD_W;

    logic [4:0]       v    = 5'b0;
    logic [5*F-1:0]   data = '0;
    logic [14:0]      cur  = 15'b0;   // 3 bits per output, scan start when empty
    logic [14:0]      src  = 15'b0;   // 3 bits per output, source of stored flit

    logic [4:0]       gv;
    logic [14:0]      gs;
    logic [4:0]       drain;
    logic [14:0]      nxt;

    always_comb begin
        int s, idx, start;
        logic [1:0] dx, dy;
        logic [24:0] rq;
        logic [4:0]  rdy;
        logic [4:0]  g;
        logic [14:0] gsrc;
        logic [14:0] nx;

        rq = 25'b0;
        for (int i = 0; i < 5; i++) begin
            dx = in_flit[i*F + PAYLOAD_W + 2 +: 2];
            dy = in_flit[i*F + PAYLOAD_W +: 2];
            if (in_valid[i]) begin
                if (dx > X)      rq[2*5+i] = 1'b1;
                else if (dx < X) rq[3*5+i] = 1'b1;
                else if (dy > Y) rq[0*5+i] = 1'b1;
                else if (dy < Y) rq[1*5+i] = 1'b1;
                else             rq[4*5+i] = 1'b1;
            end
        end

        rdy  = 5'b0;
        g    = 5'b0;
        gsrc = 15'b0;
        nx   = 15'b0;
        for (int o = 0; o < 5; o++) begin
            s = (int'(src[o*3 +: 3]) + 1) % 5;
            nx[o*3 +: 3] = 3'(s);
            if (v[o]) start = s;
            else      start = int'(cur[o*3 +: 3]) % 5;
            if (!rst && (!v[o] || out_ready[o])) begin
                for (int k = 0; k < 5; k++) begin
                    idx = (start + k) % 5;
                    if (!g[o] && rq[o*5+idx]) begin
                        g[o] = 1'b1;
                        gsrc[o*3 +: 3] = 3'(idx);
                    end
                end
            end
            if (g[o]) rdy[int'(gsrc[o*3 +: 3])] = 1'b1;
        end

        gv       = g;
        gs       = gsrc;
        nxt      = nx;
        in_ready = rdy;
        drain    = v & out_ready;
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            v    <= 5'b0;
            cur  <= 15'b0;
            src  <= 15'b0;
            data <= '0;
        end else begin
            for (int o = 0; o < 5; o++) begin
                if (drain[o])
                    cur[o*3 +: 3] <= nxt[o*3 +: 3];
                if (gv[o]) begin
                    v[o] <= 1'b1;
                    data[o*F +: F] <= in_flit[int'(gs[o*3 +: 3])*F +: F];
                    src[o*3 +: 3] <= gs[o*3 +: 3];
                end else if (drain[o]) begin
                    v[o] <= 1'b0;
                end
            end
        end
    end

    assign out_valid = v;
    always_comb begin
        for (int o = 0; o < 5; o++)
            out_flit[o*F +: F] = v[o] ? data[o*F +: F] : {F{1'b0}};
    end
endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);
    localparam int F = 4 + PAYLOAD_W;

    logic [4:0]   v;
    logic [F-1:0] data [5];
    logic [2:0]   src  [5];
    logic [2:0]   cur  [5];

    logic [2:0] dest [5];      // requested output per input
    logic [4:0] gnt  [5];      // gnt[o][i]
    logic       gany [5];
    logic [2:0] gsrc [5];

    always_comb begin
        for (int i = 0; i < 5; i++) begin
            logic [1:0] dx, dy;
            dx = in_flit[i*F + PAYLOAD_W + 2 +: 2];
            dy = in_flit[i*F + PAYLOAD_W +: 2];
            if (dx > X)      dest[i] = 3'd2;
            else if (dx < X) dest[i] = 3'd3;
            else if (dy > Y) dest[i] = 3'd0;
            else if (dy < Y) dest[i] = 3'd1;
            else             dest[i] = 3'd4;
        end

        in_ready = 5'b0;
        for (int o = 0; o < 5; o++) begin
            int s;
            int idx;
            logic found;
            logic avail;
            avail = !v[o] || out_ready[o];
            if (v[o]) s = (src[o] == 3'd4) ? 0 : int'(src[o]) + 1;
            else      s = int'(cur[o]);
            gnt[o]  = 5'b0;
            gany[o] = 1'b0;
            gsrc[o] = 3'd0;
            found   = 1'b0;
            for (int k = 0; k < 5; k++) begin
                idx = (s + k) % 5;
                if (avail && !found && in_valid[idx] && dest[idx] == 3'(o)) begin
                    found = 1'b1;
                    gnt[o][idx] = 1'b1;
                    gany[o] = 1'b1;
                    gsrc[o] = 3'(idx);
                end
            end
            if (!rst) in_ready = in_ready | gnt[o];
        end
    end

    always_ff @(posedge clk) begin
        for (int o = 0; o < 5; o++) begin
            if (rst) begin
                v[o]   <= 1'b0;
                cur[o] <= 3'd0;
                src[o] <= 3'd0;
                data[o] <= '0;
            end else begin
                if (v[o] && out_ready[o])
                    cur[o] <= (src[o] == 3'd4) ? 3'd0 : src[o] + 3'd1;
                if (gany[o]) begin
                    v[o]    <= 1'b1;
                    src[o]  <= gsrc[o];
                    data[o] <= in_flit[int'(gsrc[o])*F +: F];
                end else if (v[o] && out_ready[o]) begin
                    v[o] <= 1'b0;
                end
            end
        end
    end

    always_comb begin
        out_valid = v;
        for (int o = 0; o < 5; o++)
            out_flit[o*F +: F] = v[o] ? data[o] : '0;
    end
endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);
    localparam int F = 4 + PAYLOAD_W;

    logic [4:0]       v;
    logic [5*F-1:0]   data;
    logic [14:0]      src;     // 3 bits per output
    logic [14:0]      cur;     // 3 bits per output

    logic [14:0]      dest;    // 3 bits per input
    logic [4:0]       gany;
    logic [14:0]      gsrc;
    logic [4:0]       rdy;

    always_comb begin : route_arb
        int s, idx;
        logic found;
        logic [1:0] dx, dy;
        logic [2:0] sv, cv;

        dest = '0;
        for (int i = 0; i < 5; i++) begin
            dx = in_flit[i*F + PAYLOAD_W + 2 +: 2];
            dy = in_flit[i*F + PAYLOAD_W +: 2];
            if (dx > X)      dest[i*3 +: 3] = 3'd2;
            else if (dx < X) dest[i*3 +: 3] = 3'd3;
            else if (dy > Y) dest[i*3 +: 3] = 3'd0;
            else if (dy < Y) dest[i*3 +: 3] = 3'd1;
            else             dest[i*3 +: 3] = 3'd4;
        end

        rdy  = 5'b0;
        gany = 5'b0;
        gsrc = '0;
        for (int o = 0; o < 5; o++) begin
            sv = src[o*3 +: 3];
            cv = cur[o*3 +: 3];
            if (v[o]) s = (sv == 3'd4) ? 0 : int'(sv) + 1;
            else      s = int'(cv);
            found = 1'b0;
            for (int k = 0; k < 5; k++) begin
                idx = (s + k) % 5;
                if ((!v[o] || out_ready[o]) && !found && in_valid[idx] &&
                    (int'(dest[idx*3 +: 3]) == o)) begin
                    found = 1'b1;
                    rdy[idx] = 1'b1;
                    gany[o] = 1'b1;
                    gsrc[o*3 +: 3] = 3'(idx);
                end
            end
        end
        in_ready = rst ? 5'b0 : rdy;
    end

    always_ff @(posedge clk) begin
        for (int o = 0; o < 5; o++) begin
            if (rst) begin
                v[o]            <= 1'b0;
                cur[o*3 +: 3]   <= 3'd0;
                src[o*3 +: 3]   <= 3'd0;
                data[o*F +: F]  <= '0;
            end else begin
                if (v[o] && out_ready[o])
                    cur[o*3 +: 3] <= (src[o*3 +: 3] == 3'd4) ? 3'd0 : src[o*3 +: 3] + 3'd1;
                if (gany[o]) begin
                    v[o]           <= 1'b1;
                    src[o*3 +: 3]  <= gsrc[o*3 +: 3];
                    data[o*F +: F] <= in_flit[int'(gsrc[o*3 +: 3])*F +: F];
                end else if (v[o] && out_ready[o]) begin
                    v[o] <= 1'b0;
                end
            end
        end
    end

    always_comb begin
        out_valid = v;
        for (int o = 0; o < 5; o++)
            out_flit[o*F +: F] = v[o] ? data[o*F +: F] : '0;
    end
endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);
    localparam int F = 4 + PAYLOAD_W;

    // registered state (defined values even before the first reset edge)
    logic [4:0]       v    = 5'b0;
    logic [5*F-1:0]   data = '0;
    logic [14:0]      src  = '0;   // 3 bits per output: source of held flit
    logic [14:0]      cur  = '0;   // 3 bits per output: cursor

    logic [14:0]      dest;        // 3 bits per input: requested output
    logic [4:0]       gany;        // per output: a grant is made
    logic [14:0]      gsrc;        // per output: granted input
    logic [4:0]       rdy;         // per input: granted

    // routing
    always_comb begin : route
        logic [1:0] dx, dy;
        dest = '0;
        for (int i = 0; i < 5; i++) begin
            dx = in_flit[i*F + PAYLOAD_W + 2 +: 2];
            dy = in_flit[i*F + PAYLOAD_W +: 2];
            if (dx > X)      dest[i*3 +: 3] = 3'd2;
            else if (dx < X) dest[i*3 +: 3] = 3'd3;
            else if (dy > Y) dest[i*3 +: 3] = 3'd0;
            else if (dy < Y) dest[i*3 +: 3] = 3'd1;
            else             dest[i*3 +: 3] = 3'd4;
        end
    end

    // arbitration
    always_comb begin : arb
        int s, idx;
        logic found;
        logic [2:0] sv, cv;
        rdy  = 5'b0;
        gany = 5'b0;
        gsrc = '0;
        for (int o = 0; o < 5; o++) begin
            sv = src[o*3 +: 3];
            cv = cur[o*3 +: 3];
            if (v[o]) s = (sv == 3'd4) ? 0 : int'(sv) + 1;
            else      s = int'(cv);
            found = 1'b0;
            for (int k = 0; k < 5; k++) begin
                idx = (s + k) % 5;
                if ((!v[o] || out_ready[o]) && !found && in_valid[idx] &&
                    (int'(dest[idx*3 +: 3]) == o)) begin
                    found = 1'b1;
                    rdy[idx] = 1'b1;
                    gany[o] = 1'b1;
                    gsrc[o*3 +: 3] = 3'(idx);
                end
            end
        end
    end

    assign in_ready = rst ? 5'b0 : rdy;

    always_ff @(posedge clk) begin
        for (int o = 0; o < 5; o++) begin
            if (rst) begin
                v[o]            <= 1'b0;
                cur[o*3 +: 3]   <= 3'd0;
                src[o*3 +: 3]   <= 3'd0;
                data[o*F +: F]  <= '0;
            end else begin
                if (v[o] && out_ready[o])
                    cur[o*3 +: 3] <= (src[o*3 +: 3] == 3'd4) ? 3'd0 : src[o*3 +: 3] + 3'd1;
                if (gany[o]) begin
                    v[o]           <= 1'b1;
                    src[o*3 +: 3]  <= gsrc[o*3 +: 3];
                    data[o*F +: F] <= in_flit[int'(gsrc[o*3 +: 3])*F +: F];
                end else if (v[o] && out_ready[o]) begin
                    v[o] <= 1'b0;
                end
            end
        end
    end

    assign out_valid = v;

    always_comb begin : outs
        for (int o = 0; o < 5; o++)
            out_flit[o*F +: F] = v[o] ? data[o*F +: F] : '0;
    end
endmodule

module axil_regs (
    input  logic        clk,
    input  logic        rst,
    input  logic [31:0] status_in,
    input  logic [31:0] irq_set,

    input  logic [3:0]  s_axi_awaddr,
    input  logic [2:0]  s_axi_awprot,
    input  logic        s_axi_awvalid,
    output logic        s_axi_awready,

    input  logic [31:0] s_axi_wdata,
    input  logic [3:0]  s_axi_wstrb,
    input  logic        s_axi_wvalid,
    output logic        s_axi_wready,

    output logic [1:0]  s_axi_bresp,
    output logic        s_axi_bvalid,
    input  logic        s_axi_bready,

    input  logic [3:0]  s_axi_araddr,
    input  logic [2:0]  s_axi_arprot,
    input  logic        s_axi_arvalid,
    output logic        s_axi_arready,

    output logic [31:0] s_axi_rdata,
    output logic [1:0]  s_axi_rresp,
    output logic        s_axi_rvalid,
    input  logic        s_axi_rready
);
    logic        aw_full, w_full;
    logic [3:0]  aw_addr;
    logic [31:0] w_data;
    logic [3:0]  w_strb;
    logic [31:0] ctrl, scratch, irq;

    assign s_axi_awready = !aw_full && !s_axi_bvalid && !rst;
    assign s_axi_wready  = !w_full  && !s_axi_bvalid && !rst;
    assign s_axi_arready = !s_axi_rvalid && !rst;

    logic [31:0] wmask;
    assign wmask = {{8{w_strb[3]}}, {8{w_strb[2]}}, {8{w_strb[1]}}, {8{w_strb[0]}}};

    logic commit;
    assign commit = aw_full && w_full;

    logic wr_ok;
    assign wr_ok = (aw_addr[1:0] == 2'b00) && (aw_addr[3:2] != 2'b01);

    logic        rd_ok;
    logic [31:0] rd_val;
    assign rd_ok = (s_axi_araddr[1:0] == 2'b00);
    always_comb begin
        case (s_axi_araddr[3:2])
            2'd0:    rd_val = ctrl;
            2'd1:    rd_val = status_in;
            2'd2:    rd_val = scratch;
            default: rd_val = irq;
        endcase
        if (!rd_ok) rd_val = 32'd0;
    end

    logic [31:0] clr_mask;
    assign clr_mask = (commit && wr_ok && aw_addr[3:2] == 2'd3) ? (w_data & wmask) : 32'd0;

    always_ff @(posedge clk) begin
        if (rst) begin
            aw_full      <= 1'b0;
            w_full       <= 1'b0;
            aw_addr      <= 4'd0;
            w_data       <= 32'd0;
            w_strb       <= 4'd0;
            ctrl         <= 32'd0;
            scratch      <= 32'd0;
            irq          <= 32'd0;
            s_axi_bvalid <= 1'b0;
            s_axi_bresp  <= 2'b00;
            s_axi_rvalid <= 1'b0;
            s_axi_rdata  <= 32'd0;
            s_axi_rresp  <= 2'b00;
        end else begin
            irq <= (irq & ~clr_mask) | irq_set;

            // write address / data slots
            if (s_axi_awvalid && s_axi_awready) begin
                aw_full <= 1'b1;
                aw_addr <= s_axi_awaddr;
            end
            if (s_axi_wvalid && s_axi_wready) begin
                w_full <= 1'b1;
                w_data <= s_axi_wdata;
                w_strb <= s_axi_wstrb;
            end

            if (commit) begin
                aw_full      <= 1'b0;
                w_full       <= 1'b0;
                s_axi_bvalid <= 1'b1;
                s_axi_bresp  <= wr_ok ? 2'b00 : 2'b10;
                if (wr_ok) begin
                    if (aw_addr[3:2] == 2'd0)
                        ctrl <= (ctrl & ~wmask) | (w_data & wmask);
                    else if (aw_addr[3:2] == 2'd2)
                        scratch <= (scratch & ~wmask) | (w_data & wmask);
                end
            end else if (s_axi_bvalid && s_axi_bready) begin
                s_axi_bvalid <= 1'b0;
            end

            // read
            if (s_axi_arvalid && s_axi_arready) begin
                s_axi_rvalid <= 1'b1;
                s_axi_rdata  <= rd_val;
                s_axi_rresp  <= (rd_ok && s_axi_araddr[3:2] != 2'b00 || rd_ok && s_axi_araddr[3:2] == 2'b00)
                                ? 2'b00 : 2'b10;
            end else if (s_axi_rvalid && s_axi_rready) begin
                s_axi_rvalid <= 1'b0;
            end
        end
    end
endmodule

module axil_regs (
    input  logic        clk,
    input  logic        rst,
    input  logic [31:0] status_in,
    input  logic [31:0] irq_set,

    input  logic [3:0]  s_axi_awaddr,
    input  logic [2:0]  s_axi_awprot,
    input  logic        s_axi_awvalid,
    output logic        s_axi_awready,

    input  logic [31:0] s_axi_wdata,
    input  logic [3:0]  s_axi_wstrb,
    input  logic        s_axi_wvalid,
    output logic        s_axi_wready,

    output logic [1:0]  s_axi_bresp,
    output logic        s_axi_bvalid,
    input  logic        s_axi_bready,

    input  logic [3:0]  s_axi_araddr,
    input  logic [2:0]  s_axi_arprot,
    input  logic        s_axi_arvalid,
    output logic        s_axi_arready,

    output logic [31:0] s_axi_rdata,
    output logic [1:0]  s_axi_rresp,
    output logic        s_axi_rvalid,
    input  logic        s_axi_rready
);

    logic [31:0] ctrl, scratch, irq;
    logic        aw_full, w_full;
    logic [3:0]  aw_addr;
    logic [31:0] w_data;
    logic [3:0]  w_strb;

    logic [31:0] strb_mask;
    assign strb_mask = {{8{w_strb[3]}}, {8{w_strb[2]}}, {8{w_strb[1]}}, {8{w_strb[0]}}};

    assign s_axi_awready = !aw_full && !s_axi_bvalid && !rst;
    assign s_axi_wready  = !w_full  && !s_axi_bvalid && !rst;
    assign s_axi_arready = !s_axi_rvalid && !rst;

    logic commit;
    assign commit = aw_full && w_full;

    always_ff @(posedge clk) begin
        if (rst) begin
            ctrl         <= 32'b0;
            scratch      <= 32'b0;
            irq          <= 32'b0;
            aw_full      <= 1'b0;
            w_full       <= 1'b0;
            aw_addr      <= 4'b0;
            w_data       <= 32'b0;
            w_strb       <= 4'b0;
            s_axi_bvalid <= 1'b0;
            s_axi_bresp  <= 2'b00;
            s_axi_rvalid <= 1'b0;
            s_axi_rdata  <= 32'b0;
            s_axi_rresp  <= 2'b00;
        end else begin
            // IRQ set (default path)
            irq <= irq | irq_set;

            // Write address / data capture
            if (s_axi_awvalid && s_axi_awready) begin
                aw_full <= 1'b1;
                aw_addr <= s_axi_awaddr;
            end
            if (s_axi_wvalid && s_axi_wready) begin
                w_full <= 1'b1;
                w_data <= s_axi_wdata;
                w_strb <= s_axi_wstrb;
            end

            // Write commit
            if (commit) begin
                aw_full      <= 1'b0;
                w_full       <= 1'b0;
                s_axi_bvalid <= 1'b1;
                if (aw_addr[1:0] != 2'b00 || aw_addr == 4'h4) begin
                    s_axi_bresp <= 2'b10;
                end else begin
                    s_axi_bresp <= 2'b00;
                    case (aw_addr[3:2])
                        2'd0: ctrl    <= (ctrl & ~strb_mask) | (w_data & strb_mask);
                        2'd2: scratch <= (scratch & ~strb_mask) | (w_data & strb_mask);
                        2'd3: irq     <= (irq & ~(w_data & strb_mask)) | irq_set;
                        default: ;
                    endcase
                end
            end

            if (s_axi_bvalid && s_axi_bready)
                s_axi_bvalid <= 1'b0;

            // Read
            if (s_axi_arvalid && s_axi_arready) begin
                s_axi_rvalid <= 1'b1;
                if (s_axi_araddr[1:0] != 2'b00) begin
                    s_axi_rdata <= 32'b0;
                    s_axi_rresp <= 2'b10;
                end else begin
                    s_axi_rresp <= 2'b00;
                    case (s_axi_araddr[3:2])
                        2'd0: s_axi_rdata <= ctrl;
                        2'd1: s_axi_rdata <= status_in;
                        2'd2: s_axi_rdata <= scratch;
                        default: s_axi_rdata <= irq;
                    endcase
                end
            end

            if (s_axi_rvalid && s_axi_rready)
                s_axi_rvalid <= 1'b0;
        end
    end

    logic unused;
    assign unused = &{1'b0, s_axi_awprot, s_axi_arprot};

endmodule

module axil_regs (
    input  logic        clk,
