    assign s_axi_wready  = !w_have  && !s_axi_bvalid && !rst;
    assign s_axi_arready = !s_axi_rvalid && !rst;

    assign bmask  = {{8{w_strb[3]}}, {8{w_strb[2]}}, {8{w_strb[1]}}, {8{w_strb[0]}}};
    assign commit = aw_have && w_have;

    logic [31:0] clr;
    assign clr = (commit && aw_addr == 4'hC) ? (w_data & bmask) : 32'h0;

    always_ff @(posedge clk) begin
        if (rst) begin
            ctrl         <= 32'h0;
            scratch      <= 32'h0;
            irq          <= 32'h0;
            aw_have      <= 1'b0;
            w_have       <= 1'b0;
            aw_addr      <= 4'h0;
            w_data       <= 32'h0;
            w_strb       <= 4'h0;
            s_axi_bvalid <= 1'b0;
            s_axi_bresp  <= 2'b00;
            s_axi_rvalid <= 1'b0;
            s_axi_rdata  <= 32'h0;
            s_axi_rresp  <= 2'b00;
        end else begin
            irq <= (irq & ~clr) | irq_set;

            // write address / data slots
            if (s_axi_awvalid && s_axi_awready) begin
                aw_have <= 1'b1;
                aw_addr <= s_axi_awaddr;
