module mul_pipe3 #(
    parameter integer WIDTH = 16
) (
    input  logic                      clk,
    input  logic                      rst,
    input  logic                      in_valid,
    input  logic signed [WIDTH-1:0]   a,
    input  logic signed [WIDTH-1:0]   b,
    output logic                      out_valid,
    output logic signed [2*WIDTH-1:0] product
);

    // Pipeline: edge k captures operands (s1), k+1 multiplies (s2),
    // k+2 passes (s3), k+3 drives outputs.
    logic signed [WIDTH-1:0]   a1, b1;
    logic                      v1;
    logic signed [2*WIDTH-1:0] p2, p3;
    logic                      v2, v3;

    always_ff @(posedge clk) begin
        if (rst) begin
            a1        <= '0;
            b1        <= '0;
            v1        <= 1'b0;
            p2        <= '0;
            v2        <= 1'b0;
            p3        <= '0;
            v3        <= 1'b0;
            product   <= '0;
            out_valid <= 1'b0;
        end else begin
            // stage 1: capture operands (zeroed on bubble)
            v1 <= in_valid;
            a1 <= in_valid ? a : '0;
            b1 <= in_valid ? b : '0;
            // stage 2: multiply (zero operands give zero on bubbles)
            v2 <= v1;
            p2 <= a1 * b1;
            // stage 3
            v3 <= v2;
            p3 <= p2;
            // output stage
            out_valid <= v3;
            product   <= p3;
        end
    end

endmodule

module mul_pipe3 #(
    parameter integer WIDTH = 16
) (
    input  logic                      clk,
    input  logic                      rst,
    input  logic                      in_valid,
    input  logic signed [WIDTH-1:0]   a,
    input  logic signed [WIDTH-1:0]   b,
    output logic                      out_valid,
    output logic signed [2*WIDTH-1:0] product
);

    logic signed [WIDTH-1:0]   a1, b1;
    logic                      v1, v2, v3;
    logic signed [2*WIDTH-1:0] p2, p3;
    logic signed [2*WIDTH-1:0] prod_w;

    assign prod_w = a1 * b1;

    always_ff @(posedge clk) begin
        if (rst) begin
            v1        <= 1'b0;
            v2        <= 1'b0;
            v3        <= 1'b0;
            out_valid <= 1'b0;
            p2        <= '0;
            p3        <= '0;
            product   <= '0;
        end else begin
            v1 <= in_valid;
            v2 <= v1;
            v3 <= v2;
            out_valid <= v3;
            p2      <= v1 ? prod_w : '0;
            p3      <= p2;
            product <= p3;
        end
    end

    always_ff @(posedge clk) begin
        a1 <= a;
        b1 <= b;
    end

endmodule

module mul_pipe3 #(
    parameter integer WIDTH = 16
) (
    input  logic                      clk,
    input  logic                      rst,
    input  logic                      in_valid,
    input  logic signed [WIDTH-1:0]   a,
    input  logic signed [WIDTH-1:0]   b,
    output logic                      out_valid,
    output logic signed [2*WIDTH-1:0] product
);

    logic                      v1, v2, v3;
    logic signed [WIDTH-1:0]   a1, b1;
    logic signed [2*WIDTH-1:0] p2, p3;

    always_ff @(posedge clk) begin
        if (rst) begin
            v1        <= 1'b0;
            v2        <= 1'b0;
            v3        <= 1'b0;
            out_valid <= 1'b0;
            a1        <= '0;
            b1        <= '0;
            p2        <= '0;
            p3        <= '0;
            product   <= '0;
        end else begin
            // stage 1: capture
            v1 <= in_valid;
            a1 <= in_valid ? a : '0;
            b1 <= in_valid ? b : '0;
            // stage 2: multiply
            v2 <= v1;
            p2 <= v1 ? (a1 * b1) : '0;
            // stage 3: pass
            v3 <= v2;
            p3 <= p2;
            // stage 4: output
            out_valid <= v3;
            product   <= p3;
        end
    end

endmodule

module mul_pipe3 #(
    parameter integer WIDTH = 16
) (
    input  logic                      clk,
