    input  logic signed [WIDTH-1:0]   a,
    input  logic signed [WIDTH-1:0]   b,
    output logic                      out_valid,
    output logic signed [2*WIDTH-1:0] product
);

    logic signed [WIDTH-1:0]   a0, b0;
    logic signed [2*WIDTH-1:0] p1, p2;
    logic                      v0, v1, v2;

    always_ff @(posedge clk) begin
        a0 <= a;
        b0 <= b;
        p1 <= a0 * b0;
        p2 <= p1;
        if (rst) begin
            v0        <= 1'b0;
            v1        <= 1'b0;
            v2        <= 1'b0;
            out_valid <= 1'b0;
            product   <= '0;
        end else begin
            v0        <= in_valid;
            v1        <= v0;
            v2        <= v1;
            out_valid <= v2;
            product   <= v2 ? p2 : '0;
        end
    end

endmodule

module crc32_stream (
    input  logic        clk,
    input  logic        rst,
    input  logic        start,
    input  logic        in_valid,
    input  logic [7:0]  data,
    output logic        out_valid,
    output logic [31:0] crc
);

    logic [31:0] rem_q;

    function automatic logic [31:0] crc_byte(input logic [31:0] r_in,
                                             input logic [7:0]  d);
        logic [31:0] r;
        logic        mix;
        r = r_in;
        for (int i = 0; i < 8; i++) begin
            mix = r[0] ^ d[i];
            r   = {1'b0, r[31:1]};
            if (mix) r = r ^ 32'hEDB8_8320;
        end
        return r;
    endfunction

    logic [31:0] base;
    assign base = start ? 32'hFFFF_FFFF : rem_q;

    always_ff @(posedge clk) begin
        if (rst) begin
            rem_q     <= 32'hFFFF_FFFF;
            out_valid <= 1'b0;
        end else begin
            out_valid <= in_valid;
            rem_q     <= in_valid ? crc_byte(base, data) : base;
        end
    end

    assign crc = ~rem_q;

endmodule

module crc32_stream (
    input  logic        clk,
    input  logic        rst,
    input  logic        start,
    input  logic        in_valid,
    input  logic [7:0]  data,
    output logic        out_valid,
    output logic [31:0] crc
);

    logic [31:0] rem_q;

    // Process one byte, bit 0 first, reflected CRC-32 polynomial.
    function automatic logic [31:0] crc_byte(input logic [31:0] r, input logic [7:0] d);
        logic [31:0] x;
        logic        mix;
        x = r;
        for (int i = 0; i < 8; i++) begin
            mix = x[0] ^ d[i];
            x   = {1'b0, x[31:1]};
            if (mix) x = x ^ 32'hEDB8_8320;
        end
        return x;
    endfunction

    logic [31:0] base;
    assign base = start ? 32'hFFFF_FFFF : rem_q;

    always_ff @(posedge clk) begin
        if (rst) begin
            rem_q     <= 32'hFFFF_FFFF;
            out_valid <= 1'b0;
        end else begin
            rem_q     <= in_valid ? crc_byte(base, data) : base;
            out_valid <= in_valid;
        end
    end

    assign crc = ~rem_q;

endmodule

module crc32_stream (
    input  logic        clk,
    input  logic        rst,
    input  logic        start,
    input  logic        in_valid,
    input  logic [7:0]  data,
    output logic        out_valid,
    output logic [31:0] crc
);

    logic [31:0] rem_q;
    logic        valid_q;

    function automatic logic [31:0] crc_byte(input logic [31:0] r, input logic [7:0] d);
        logic [31:0] x;
        logic        mix;
        x = r;
        for (int i = 0; i < 8; i++) begin
            mix = x[0] ^ d[i];
            x   = (x >> 1) ^ (mix ? 32'hEDB8_8320 : 32'h0);
        end
        return x;
    endfunction

    logic [31:0] base;
    assign base = start ? 32'hFFFF_FFFF : rem_q;

    always_ff @(posedge clk) begin
        if (rst) begin
            rem_q   <= 32'hFFFF_FFFF;
            valid_q <= 1'b0;
        end else begin
            rem_q   <= in_valid ? crc_byte(base, data) : base;
            valid_q <= in_valid;
        end
    end

    assign out_valid = valid_q;
    assign crc       = ~rem_q;

endmodule

module crc32_stream (
    input  logic        clk,
    input  logic        rst,
    input  logic        start,
    input  logic        in_valid,
    input  logic [7:0]  data,
    output logic        out_valid,
    output logic [31:0] crc
);
    logic [31:0] rem_q;

    // Bitwise CRC-32 update over one byte, bit 0 first
    function automatic logic [31:0] crc_byte(input logic [31:0] r, input logic [7:0] d);
        logic [31:0] x;
        x = r;
        for (int i = 0; i < 8; i++) begin
            if (x[0] ^ d[i]) x = (x >> 1) ^ 32'hEDB8_8320;
            else             x = x >> 1;
        end
        return x;
    endfunction

    logic [31:0] base;
    assign base = start ? 32'hFFFF_FFFF : rem_q;

    always_ff @(posedge clk) begin
        if (rst) begin
            rem_q     <= 32'hFFFF_FFFF;
            out_valid <= 1'b0;
        end else begin
            rem_q     <= in_valid ? crc_byte(base, data) : base;
            out_valid <= in_valid;
        end
    end

    assign crc = rem_q ^ 32'hFFFF_FFFF;
endmodule

